const std = @import("std");

pub fn main() !void {
    const graph = [_][5]u8{
        [_]u8{ 0, 1, 0, 0, 0 },
        [_]u8{ 0, 0, 1, 1, 0 },
        [_]u8{ 0, 0, 0, 0, 1 },
        [_]u8{ 0, 0, 0, 0, 1 },
        [_]u8{ 0, 0, 0, 0, 0 },
    };
    var in_degree = [_]u8{ 0, 0, 0, 0, 0 };

    for (0..5) |i| {
        for (0..5) |j| {
            if (graph[i][j] == 1) in_degree[j] += 1;
        }
    }

    var queue: [5]u8 = undefined;
    var front: usize = 0;
    var rear: usize = 0;

    for (0..5) |i| {
        if (in_degree[i] == 0) { queue[rear] = @intCast(i); rear += 1; }
    }

    var count: usize = 0;
    while (front < rear) {
        const node = queue[front]; front += 1;
        std.debug.print("{} ", .{node});
        count += 1;
        for (0..5) |j| {
            if (graph[node][j] == 1) {
                in_degree[j] -= 1;
                if (in_degree[j] == 0) { queue[rear] = @intCast(j); rear += 1; }
            }
        }
    }
    std.debug.print("\n", .{});
}

